// =============================================
// Read runtime settings from Google Sheets
// =============================================

const rows = $input.all().map(item => item.json);

const settings = {
  environment: 'QA',
  responseTimeThresholdMs: 3000,
  retryCount: 2,
  retryDelayMs: 5000,
  retryDelayMs2: 30000,
  application: 'VWO'
};

for (const row of rows) {
  const key = String(row.Key || '').trim();
  const rawValue = row.Value;

  if (!key) {
    continue;
  }

  switch (key) {
    case 'environment':
      settings.environment = String(rawValue || 'QA');
      break;

    case 'responseTimeThresholdMs':
      settings.responseTimeThresholdMs =
        Number(rawValue) || 3000;
      break;

    case 'retryCount':
      settings.retryCount =
        Number.isFinite(Number(rawValue))
          ? Number(rawValue)
          : 2;
      break;

    case 'retryDelayMs':
      settings.retryDelayMs =
        Number(rawValue) || 5000;
      break;

    case 'retryDelayMs2':
      settings.retryDelayMs2 =
        Number(rawValue) || 30000;
      break;

    case 'application':
      settings.application =
        String(rawValue || 'VWO');
      break;
  }
}


// =============================================
// Get environment supplied by API, if any
// =============================================

let requestedEnvironment = '';

try {
  requestedEnvironment =
    $('02A - Resolve Monitor Context')
      .first()
      .json
      .requestedEnvironment || '';
} catch (e) {
  requestedEnvironment = '';
}


// API environment takes priority.
// Otherwise use Settings sheet.
// Otherwise QA.
const environment =
  requestedEnvironment ||
  settings.environment ||
  'QA';


// =============================================
// Current workflow supports maximum 2 retries
// initial attempt + retry #2 + retry #3
// =============================================

const configuredRetryCount = Math.min(
  Math.max(Number(settings.retryCount) || 0, 0),
  2
);


// =============================================
// Services
// =============================================

const services = [
  {
    application: settings.application,
    environment,
    serviceName: 'VWO Main Application',
    checkType: 'HTTP',
    url: 'https://app.vwo.com/',
    method: 'GET',
    expectedStatus: 200,
    expectedText: '',
    critical: true
  },

  {
    application: settings.application,
    environment,
    serviceName: 'VWO Login',
    checkType: 'HTTP',
    url: 'https://app.vwo.com/',
    method: 'GET',
    expectedStatus: 200,
    expectedText: '',
    critical: true
  },

  {
    application: settings.application,
    environment,
    serviceName: 'VWO Campaign Dashboard',
    checkType: 'HTTP',
    url: 'https://app.vwo.com/',
    method: 'GET',
    expectedStatus: 200,
    expectedText: '',
    critical: false
  },

  {
    application: settings.application,
    environment,
    serviceName: 'VWO API',
    checkType: 'HTTP',
    url: 'https://app.vwo.com/',
    method: 'GET',
    expectedStatus: 200,
    expectedText: '',
    critical: true
  },

  {
    application: settings.application,
    environment,
    serviceName: 'VWO Editor',
    checkType: 'HTTP',
    url: 'https://app.vwo.com/',
    method: 'GET',
    expectedStatus: 200,
    expectedText: '',
    critical: false
  }
];


// =============================================
// Return one n8n item per service
// =============================================

return services.map(service => ({
  json: {
    ...service,

    responseTimeThresholdMs:
      settings.responseTimeThresholdMs,

    retryDelayMs:
      settings.retryDelayMs,

    retryDelayMs2:
      settings.retryDelayMs2,

    configuredRetryCount,

    attempt: 1,

    maxAttempts:
      configuredRetryCount + 1
  }
}));

const cfg = $json;
const started = Date.now();

let httpStatus = null;
let body = '';
let errorMessage = '';
let rawError = '';

function safeStringify(value) {
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function extractErrorMessage(error) {
  if (!error) {
    return 'Unknown HTTP request error';
  }

  // Clean DNS error
  if (error.code === 'ENOTFOUND') {
    return `DNS lookup failed: ${error.hostname || 'unknown host'}`;
  }

  // Clean timeout error
  if (
    error.code === 'ETIMEDOUT' ||
    error.code === 'ESOCKETTIMEDOUT'
  ) {
    return 'Request timed out';
  }

  // Connection refused
  if (error.code === 'ECONNREFUSED') {
    return `Connection refused${
      error.address ? `: ${error.address}` : ''
    }`;
  }

  // Connection reset
  if (error.code === 'ECONNRESET') {
    return 'Connection reset by remote server';
  }

  // Normal error message
  if (
    typeof error.message === 'string' &&
    error.message.trim()
  ) {
    return error.message;
  }

  // Sometimes message itself is an object
  if (
    error.message &&
    typeof error.message === 'object'
  ) {
    if (
      typeof error.message.message === 'string' &&
      error.message.message.trim()
    ) {
      return error.message.message;
    }

    return safeStringify(error.message);
  }

  // Nested error.message
  if (
    typeof error.error?.message === 'string' &&
    error.error.message.trim()
  ) {
    return error.error.message;
  }

  // Nested cause.message
  if (
    typeof error.cause?.message === 'string' &&
    error.cause.message.trim()
  ) {
    return error.cause.message;
  }

  // Response body message
  if (
    typeof error.response?.body?.message === 'string' &&
    error.response.body.message.trim()
  ) {
    return error.response.body.message;
  }

  // Response body error
  if (
    typeof error.response?.body?.error === 'string' &&
    error.response.body.error.trim()
  ) {
    return error.response.body.error;
  }

  return safeStringify(error);
}

try {
  const response = await this.helpers.httpRequest({
    method: cfg.method || 'GET',
    url: cfg.url,
    timeout: 10000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    encoding: 'text'
  });

  httpStatus =
    Number(
      response.statusCode ||
      response.status ||
      0
    ) || null;

  if (typeof response.body === 'string') {
    body = response.body;
  } else if (
    response.body !== undefined &&
    response.body !== null
  ) {
    body = safeStringify(response.body);
  }

} catch (e) {

  errorMessage = extractErrorMessage(e);
  rawError = safeStringify(e);

  httpStatus =
    Number(
      e?.statusCode ||
      e?.status ||
      e?.response?.statusCode ||
      e?.response?.status ||
      0
    ) || null;

  const errorBody =
    e?.response?.body ??
    e?.body ??
    '';

  if (typeof errorBody === 'string') {
    body = errorBody;
  } else if (errorBody) {
    body = safeStringify(errorBody);
  }
}

const responseTimeMs = Date.now() - started;

const expectedStatus =
  Number(cfg.expectedStatus || 200);

const threshold =
  Number(cfg.responseTimeThresholdMs || 3000);

const expectedText =
  String(cfg.expectedText || '');

let healthStatus = 'UP';
let functionalValidation = 'NOT_APPLICABLE';

// HTTP/network failure
if (
  !httpStatus ||
  httpStatus !== expectedStatus
) {
  healthStatus = 'DOWN';
  functionalValidation = 'NOT_APPLICABLE';
}

// HTTP succeeded but functional validation failed
else if (
  expectedText &&
  !body.includes(expectedText)
) {
  healthStatus = 'FUNCTIONAL_FAILURE';
  functionalValidation = 'FAIL';
}

// Functional validation passed
else if (expectedText) {
  functionalValidation = 'PASS';

  if (responseTimeMs > threshold) {
    healthStatus = 'DEGRADED';
  }
}

// No functional text check, only response-time check
else if (responseTimeMs > threshold) {
  healthStatus = 'DEGRADED';
}

return {
  json: {
    ...cfg,

    attempt: 1,

    httpStatus,
    responseTimeMs,

    healthStatus,
    functionalValidation,

    errorMessage,
    rawError,

    checkedAt: new Date().toISOString(),

    responseSnippet:
      typeof body === 'string'
        ? body.slice(0, 500)
        : ''
  }
};

