const row = $json;
const x = row._monitor || {};
const now = new Date();
const incidentId =
  'INC-' +
  now.toISOString().replace(/\D/g, '').slice(0, 14) +
  '-' +
  String(x.serviceName || 'service').toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 24);

return {
  json: {
    'Incident ID': incidentId,
    'Application': x.application || 'VWO',
    'Environment': x.environment || 'QA',
    'Service Name': x.serviceName || '',
    'Endpoint': x.url || '',
    'Status': 'OPEN',
    'Severity': x.critical ? 'SEV-1' : 'SEV-3',
    'Downtime Start': now.toISOString().replace('T', ' ').slice(0, 19),
    'Recovery Time': '',
    'Downtime Seconds': 0,
    'Retry Count': Math.max(0, Number(x.attempt || 3) - 1),
    'HTTP Status': x.httpStatus ?? '',
    'Response Time Ms': x.responseTimeMs ?? 0,
    'Failure Reason': x.errorMessage || x.healthStatus || 'Health check failed',
    'HTTP Response': x.responseSnippet || '',
    'Workflow Execution ID': String($execution.id)
  }
};

const rows = $input.all().map(i => i.json || {});
// History rows are stamped in server-local time, so the day key must be too:
// a UTC key excludes rows written either side of midnight on a UTC+5:30 host.
const now = new Date();
const pad2 = (n) => String(n).padStart(2, '0');
const today =
  now.getFullYear() +
  '-' +
  pad2(now.getMonth() + 1) +
  '-' +
  pad2(now.getDate());

const todayRows = rows.filter((r) => {
  const ts = String(r['Timestamp'] || r.timestamp || '');
  return ts.slice(0, 10) === today;
});

const total = todayRows.length;
const failed = todayRows.filter((r) =>
  ['DOWN', 'FUNCTIONAL_FAILURE'].includes(
    String(r['Health Status'] || r.healthStatus || '').toUpperCase()
  )
).length;

const available = total - failed;
const availabilityPct = total ? Math.round((available / total) * 10000) / 100 : 100;

return [{
  json: {
    'Date': today,
    'Application': 'VWO',
    'Environment': 'OVERALL',
    'Service Name': 'ALL_SERVICES',
    'Total Checks': total,
    'Failed Checks': failed,
    'Availability Percentage': availabilityPct,
    'Updated At': new Date().toISOString()
  }
}];

const x = $json;

const status =
  x['Health Status'] ||
  x.healthStatus ||
  'UNKNOWN';

// Every check is appended, not just failures. Previously this node returned
// early for UP/DEGRADED rows, so Health_Check_History held only failures,
// latency charts had no healthy series and daily availability read ~0%.
const pad = (n) => String(n).padStart(2, '0');

function toSheetTimestamp(value) {
  if (!value) {
    return '';
  }

  const d = new Date(value);

  if (Number.isNaN(d.getTime())) {
    return String(value);
  }

  return (
    d.getFullYear() +
    '-' +
    pad(d.getMonth() + 1) +
    '-' +
    pad(d.getDate()) +
    ' ' +
    pad(d.getHours()) +
    ':' +
    pad(d.getMinutes()) +
    ':' +
    pad(d.getSeconds())
  );
}

return {
  json: {
    'Timestamp':
      x['Timestamp'] || toSheetTimestamp(x.checkedAt),

    'Application': x['Application'] || x.application || '',
    'Environment': x['Environment'] || x.environment || '',
    'Service Name': x['Service Name'] || x.serviceName || '',
    'Endpoint': x['Endpoint'] || x.url || '',

    'HTTP Status':
      x['HTTP Status'] ??
      x.httpStatus ??
      '',

    'Response Time Ms':
      x['Response Time Ms'] ??
      x.responseTimeMs ??
      0,

    'Response Time Threshold Ms':
      x['Response Time Threshold Ms'] ??
      x.responseTimeThresholdMs ??
      3000,

    'Health Status': status,

    'Functional Validation':
      x['Functional Validation'] ||
      x.functionalValidation ||
      '',

    'Retry Count':
      x['Retry Count'] ??
      x.configuredRetryCount ??
      0,

    'Error Message':
      x['Error Message'] ||
      x.errorMessage ||
      '',

    'Response Snippet':
      x['Response Snippet'] ||
      x.responseSnippet ||
      '',

    'Workflow Execution ID':
      x['Workflow Execution ID'] ||
      String($execution.id),

    'Critical':
      x['Critical'] ??
      x.critical ??
      false
  }
};

const input = $input.first()?.json || {};

const requestedEnvironment =
  input.environment ||
  input.body?.environment ||
  input.query?.environment ||
  '';

return [
  {
    json: {
      requestedEnvironment
    }
  }
];
